package vn.rtr.aeris.crew02;
import java.io.*;import java.nio.*;import java.nio.charset.*;import java.util.*;
/** Bounded flat wire envelopes. No duplicate keys, nested values, floats or permissive UTF-8. */
public final class StrictJson02{
 private final String s;private int p=0;private StrictJson02(String s){this.s=s;}
 public static Map<String,Object>parse(byte[]raw)throws IOException{if(raw.length<2||raw.length>16384)throw new IOException("CREW_FRAME_BOUND");String s=StandardCharsets.UTF_8.newDecoder().onMalformedInput(CodingErrorAction.REPORT).onUnmappableCharacter(CodingErrorAction.REPORT).decode(ByteBuffer.wrap(raw)).toString();StrictJson02 q=new StrictJson02(s);Map<String,Object>m=q.object();q.ws();if(q.p!=s.length())throw new IOException("CREW_JSON_TRAILING");return m;}
 private void ws(){while(p<s.length()&&" \r\n\t".indexOf(s.charAt(p))>=0)p++;}
 private char take()throws IOException{if(p>=s.length())throw new IOException("CREW_JSON_TRUNCATED");return s.charAt(p++);}
 private String string()throws IOException{if(take()!='"')throw new IOException("CREW_JSON_STRING");StringBuilder b=new StringBuilder();while(p<s.length()){char c=take();if(c=='"'){if(b.length()>12288)throw new IOException("CREW_JSON_STRING_BOUND");return b.toString();}if(c<32||Character.isSurrogate(c))throw new IOException("CREW_JSON_CHARACTER");if(c=='\\'){c=take();if(c=='u'){if(p+4>s.length())throw new IOException("CREW_JSON_ESCAPE");for(int j=p;j<p+4;j++)if("0123456789abcdefABCDEF".indexOf(s.charAt(j))<0)throw new IOException("CREW_JSON_ESCAPE");try{c=(char)Integer.parseInt(s.substring(p,p+4),16);}catch(Exception e){throw new IOException("CREW_JSON_ESCAPE");}p+=4;if(Character.isSurrogate(c))throw new IOException("CREW_JSON_CHARACTER");}else{int i="\"\\/bfnrt".indexOf(c);if(i<0)throw new IOException("CREW_JSON_ESCAPE");c="\"\\/\b\f\n\r\t".charAt(i);}}b.append(c);}throw new IOException("CREW_JSON_TRUNCATED");}
 private Object value()throws IOException{ws();if(p>=s.length())throw new IOException("CREW_JSON_VALUE");char c=s.charAt(p);if(c=='"')return string();for(String v:new String[]{"true","false","null"})if(s.startsWith(v,p)){p+=v.length();return v.equals("null")?null:Boolean.valueOf(v);}int a=p;if(c=='-')p++;if(p>=s.length()||!(s.charAt(p)>='0'&&s.charAt(p)<='9'))throw new IOException("CREW_JSON_INTEGER");if(s.charAt(p)=='0')p++;else while(p<s.length()&&s.charAt(p)>='0'&&s.charAt(p)<='9')p++;String n=s.substring(a,p);if(n.equals("-0"))throw new IOException("CREW_JSON_INTEGER");try{long v=Long.parseLong(n);if(v< -9007199254740991L||v>9007199254740991L)throw new IOException("CREW_JSON_UNSAFE_INTEGER");return v;}catch(NumberFormatException e){throw new IOException("CREW_JSON_INTEGER");}}
 private Map<String,Object>object()throws IOException{ws();if(take()!='{')throw new IOException("CREW_JSON_OBJECT");Map<String,Object>m=new LinkedHashMap<>();ws();if(p<s.length()&&s.charAt(p)=='}'){p++;return m;}while(true){ws();String k=string();if(k.length()>64||m.containsKey(k)||m.size()>=24)throw new IOException("CREW_JSON_DUPLICATE_OR_KEY_BOUND");ws();if(take()!=':')throw new IOException("CREW_JSON_COLON");m.put(k,value());ws();char c=take();if(c=='}')return m;if(c!=',')throw new IOException("CREW_JSON_SEPARATOR");}}
 public static void exact(Map<String,Object>q,String...keys)throws IOException{if(!q.keySet().equals(new HashSet<>(Arrays.asList(keys))))throw new IOException("CREW_REQUEST_SHAPE");}
 public static String text(Map<String,Object>q,String k)throws IOException{Object v=q.get(k);if(!(v instanceof String))throw new IOException("CREW_STRING:"+k);return(String)v;}
 public static long integer(Map<String,Object>q,String k)throws IOException{Object v=q.get(k);if(!(v instanceof Long))throw new IOException("CREW_INTEGER:"+k);return(Long)v;}
 private StrictJson02(){s="";}
}
